def test_store_is_enabled():
    with tempfile.TemporaryDirectory() as tmpdir:
        config = StorageConfig(file_storage_metadata_path=tmpdir + "/meta")
        node_configs = {
            "A": NodeFileStorageConfig(backend=LocalBackendConfig(base_path=tmpdir)),
            "B": NodeFileStorageConfig(backend=LocalBackendConfig(base_path=tmpdir), enabled=False),
        }
        store = NetFileStorageStore(config, node_configs)

        assert store.is_enabled("A")
        assert not store.is_enabled("B")
        assert not store.is_enabled("NonExistent")
        store.close()


def test_store_get_config():
    with tempfile.TemporaryDirectory() as tmpdir:
        config = StorageConfig(file_storage_metadata_path=tmpdir + "/meta")
        fs_config = NodeFileStorageConfig(backend=LocalBackendConfig(base_path=tmpdir))
        store = NetFileStorageStore(config, {"A": fs_config})

        assert store.get_config("A") is fs_config
        assert store.get_config("NonExistent") is None
        store.close()

