def test_manifest_store_and_lookup():
    with tempfile.TemporaryDirectory() as tmpdir:
        config = StorageConfig(file_storage_metadata_path=tmpdir + "/meta")
        store = NetFileStorageStore(config, {
            "A": NodeFileStorageConfig(backend=LocalBackendConfig(base_path=tmpdir)),
        })

        manifest = FileStorageManifest(
            input_salvo_hash=42,
            version=1,
            node_name="A",
            output_salvo_names=["send"],
            consumed_input_ports={"x", "y"},
            file_keys={"send": [{"out": "A/out.pkl"}]},
        )
        store.store_manifest("A", manifest)

        result = store.lookup("A")
        assert result is not None
        assert result.input_salvo_hash == 42
        assert result.version == 1
        assert result.node_name == "A"
        assert result.output_salvo_names == ["send"]
        assert result.consumed_input_ports == {"x", "y"}
        assert result.file_keys == {"send": [{"out": "A/out.pkl"}]}

        store.close()


