def test_manifest_overwrite():
    with tempfile.TemporaryDirectory() as tmpdir:
        config = StorageConfig(file_storage_metadata_path=tmpdir + "/meta")
        store = NetFileStorageStore(config, {
            "A": NodeFileStorageConfig(backend=LocalBackendConfig(base_path=tmpdir)),
        })

        m1 = FileStorageManifest(input_salvo_hash=1, version=0, node_name="A")
        store.store_manifest("A", m1)

        m2 = FileStorageManifest(input_salvo_hash=2, version=1, node_name="A")
        store.store_manifest("A", m2)

        result = store.lookup("A")
        assert result.input_salvo_hash == 2
        assert result.version == 1

        store.close()

