def test_resolve_named_backend():
    with tempfile.TemporaryDirectory() as tmpdir:
        config = StorageConfig(
            file_storage_metadata_path=tmpdir + "/meta",
            backends={
                "my_local": LocalBackendConfig(base_path=tmpdir + "/data"),
            },
        )
        store = NetFileStorageStore(config, {
            "A": NodeFileStorageConfig(backend="my_local"),
        })

        bc = store.resolve_backend_config("A")
        assert bc.type == "local"
        assert bc.base_path == tmpdir + "/data"
        store.close()


