def test_compute_input_hash_deterministic():
    """Same inputs should produce the same hash."""
    from netrun.packets import PacketStore

    store = PacketStore()
    store.register("p1", 42)
    store.register("p2", "hello")

    packets = {"x": ["p1"], "y": ["p2"]}

    h1 = compute_input_hash(
        packets, store,
        hash_method=HashMethod.xxh64,
        pickling_method=PicklingMethod.pickle,
        pickling_args={},
    )
    h2 = compute_input_hash(
        packets, store,
        hash_method=HashMethod.xxh64,
        pickling_method=PicklingMethod.pickle,
        pickling_args={},
    )
    assert h1 == h2


def test_compute_input_hash_different_values():
    """Different values should produce different hashes."""
    from netrun.packets import PacketStore

    store1 = PacketStore()
    store1.register("p1", 42)

    store2 = PacketStore()
    store2.register("p1", 99)

    h1 = compute_input_hash(
        {"x": ["p1"]}, store1,
        hash_method=HashMethod.xxh64,
        pickling_method=PicklingMethod.pickle,
        pickling_args={},
    )
    h2 = compute_input_hash(
        {"x": ["p1"]}, store2,
        hash_method=HashMethod.xxh64,
        pickling_method=PicklingMethod.pickle,
        pickling_args={},
    )
    assert h1 != h2

